  if(!project||!branch){root.innerHTML+='<div class="dsl-empty"><p>This book has no DSL workspace yet. Start it from the reusable T001 master, with no borrowed characters or plots.</p><button data-action="initialize">Create novel from T001</button> <button data-action="template-guide">View template modules</button></div>';bind();return;}
  if(mode==='storyline'){const pub=project.published;const data=pub?.data||d;root.innerHTML+='<div class="dsl-bar"><div class="dsl-inline"><a class="dsl-btn" href="'+route('dsl')+'">Open DSL</a><button data-action="export-html">HTML</button></div><span class="dsl-muted">'+(pub?'Published from '+h(pub.branch_name)+' · r'+pub.branch_revision+' · '+h(when(pub.published_at)):'Imported working preview. Not approved for publication yet.')+'</span></div>'+readable(data)+'<div class="dsl-notice">Proposals and open questions keep their status labels. Publishing Storyline does not change chapter text.</div>'+footer();bind();return;}
  root.innerHTML+='<details class="dsl-summary"><summary>Story overview · '+activeEvents(d).length+' events</summary><div class="dsl-summary-head"><h2>Synopsis · The whole story</h2><button data-action="overview">Edit synopsis</button></div><p class="dsl-synopsis-text">'+h(d.summary||'Write the premise so your collaborator can understand the story before opening the map.')+'</p><div class="dsl-stats"><span lang="en" dir="ltr" class="dsl-tag">'+activeEvents(d).length+' events</span><span lang="en" dir="ltr" class="dsl-tag">'+d.links.length+' connections</span><span lang="en" dir="ltr" class="dsl-tag">'+d.objects.length+' objects</span><span lang="en" dir="ltr" class="dsl-tag">'+getCharacters(d).length+' characters</span><span lang="en" dir="ltr" class="dsl-tag">'+activeEvents(d).filter(e=>e.status==='proposal'||e.status==='question').length+' proposals and questions</span>'+author(branch.updated_by)+'</div></details>'+(d.hypothesis?'<p class="dsl-notice"><strong>What if?</strong> '+h(d.hypothesis)+'</p>':'')+
  '<div class="dsl-bar"><nav class="dsl-tabs" aria-label="DSL views">'+[['map','Story Map'],['synopsis','Synopsis'],['paths','Paths'],['decisions','Questions & Decisions'],['twists','Twists & Clues'],['characters','Characters & World'],['reading','Scenes & Pacing'],['history','History']].map(([id,label])=>'<a href="'+route('dsl',{dslview:id})+'" '+(view===id?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav></div><div class="dsl-bar"><div class="dsl-inline"><button class="dsl-primary" data-action="new-event">＋ Event</button><button data-action="new-link">＋ Connection</button><button data-action="fork">What If? New Branch</button><button data-action="new-object">＋ Object</button></div><div class="dsl-inline"><button data-action="template-guide">Template T001</button><button data-action="preview">Preview and Publish</button><button data-action="blend" class="dsl-primary">Blend Story</button><button data-action="brief">ChatGPT Brief</button><button data-action="export">Export</button></div></div>'+
  '<div lang="en" dir="ltr" data-remote class="dsl-notice" '+(refreshNeeded?'':'hidden')+'>A newer revision is available from another device. <button data-action="refresh">Load latest</button></div>'+
  (readLocal()?'<div class="dsl-notice" lang="en" dir="ltr">This device has a draft that has not been saved for collaborators. <button data-action="recover">Recover as a separate branch</button><button data-action="discard">Discard local draft</button></div>':'')+
  '<section class="dsl-panel">'+(model().workshop?.reviewEventIds?.length?'<details class="dsl-notice"><summary>'+model().workshop.reviewEventIds.length+' connected events need review</summary>'+model().workshop.reviewEventIds.map(id=>{const e=model().events.find(x=>x.id===id);return e?'<button data-edit-event="'+h(id)+'">'+h(e.title)+'</button>':''}).join(' ')+'</details>':'')+(view==='graph'?mapHTML():view==='map'?workshop.routeHTML():view==='synopsis'?workshop.synopsisHTML():view==='paths'?workshop.pathsHTML():view==='timeline'?mapHTML(true):view==='reading'?'<p class="dsl-help" lang="en" dir="ltr">Reading order is independent of event dates. Drag scene grips or use Move to choose before or after another scene.</p><div class="dsl-sequence">'+orderEvents(d).map(e=>'<div><span lang="en" dir="ltr" class="dsl-tag">Order '+h(e.order)+'</span>'+eventCard(e)+'</div>').join('')+'</div>':view==='decisions'?workshop.questionsHTML():view==='objects'?objectsHTML():view==='characters'?charactersHTML()+worldHTML()+objectsHTML():view==='knowledge'?knowledgeHTML():view==='twists'?twistsHTML()+knowledgeHTML():view==='health'?healthHTML():view==='review'?reviewHTML():view==='history'?'<div class="dsl-inline"><a href="'+route('dsl',{dslview:'health'})+'">Story health</a><a href="'+route('dsl',{dslview:'review'})+'">Review changes</a></div><p class="dsl-muted">Loading revision history…</p>':'')+'</section>'+footer();
  bind();requestAnimationFrame(drawLines);if(view==='history')loadHistory();
