 async function archivePath(id){const b=branches.find(x=>x.id===id);if(!b||busy)return;if(project.published?.branch_id===id){status('This path is published. Publish another path before archiving it.',true);return;}if(!confirm('Archive this alternative? Its saved history remains available for restoration.'))return;busy=true;try{const rows=await api('chronicles_dsl_branches?id=eq.'+id+'&book_id=eq.'+bookId+'&revision=eq.'+b.revision,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({archived:true,updated_by:writer(),change_note:'Archive alternative path'})});if(!rows?.length)throw Error('This path changed. Reload before archiving.');await load();render();}catch(e){status(e.message,true);}finally{busy=false;}}
